draw:
var mp = 938.3;
var K = p.kinetic;
var E = K + mp;
var sFixed = Math.sqrt(2 * mp * (E + mp));
var sCollide = 2 * E;
var barMax = 2 * (8000 + mp) * 1.02;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var x0 = W * 0.06, x1 = W * 0.94;
var barW = x1 - x0;
var f = (t % 2.2) / 2.2;

function scene(yLine, yBar, label, sval, moving2) {
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(x0, yLine); ctx.lineTo(x1, yLine); ctx.stroke();

  var mid = (x0 + x1) / 2;
  var xa = x0 + (mid - x0 - 8) * f;
  var xb = moving2 ? x1 - (x1 - mid - 8) * f : mid + 10;

  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(xa, yLine, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = moving2 ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(xb, yLine, 6, 0, Math.PI * 2); ctx.fill();

  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(label, x0, yLine - 16);

  ctx.fillStyle = C.faint;
  ctx.textAlign = "center";
  ctx.fillText(moving2 ? "both beams move" : "target at rest", (x0 + x1) / 2, yLine + 20);

  // bar
  var wBar = barW * sval / barMax;
  ctx.fillStyle = C.figure;
  ctx.fillRect(x0, yBar, wBar, 12);
  ctx.strokeStyle = C.rule;
  ctx.strokeRect(x0, yBar, barW, 12);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText("sqrt(s) = " + sval.toFixed(0) + " MeV", x0 + 2, yBar + 26);
}

// threshold markers drawn across both bars
function marker(val, name, yTop, yBot) {
  var xm = x0 + barW * val / barMax;
  ctx.strokeStyle = C.accent;
  ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(xm, yTop); ctx.lineTo(xm, yBot); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText(name, xm, yTop - 4);
}

scene(H * 0.20, H * 0.34, "Fixed target:  beam on hydrogen", sFixed, false);
scene(H * 0.66, H * 0.80, "Collider:  equal and opposite beams", sCollide, true);

marker(2 * mp + 135.0, "pi⁰", H * 0.30, H * 0.94);
marker(4 * mp, "p pbar", H * 0.30, H * 0.94);

out.note = "beam K = " + K.toFixed(0) + " MeV per proton   |   fixed target sqrt(s) = " +
  sFixed.toFixed(0) + " MeV,  collider sqrt(s) = " + sCollide.toFixed(0) +
  " MeV   |   ratio " + (sCollide / sFixed).toFixed(2);
